rong><span class="rounded-lg bg-green-50 px-3 py-2 text-green-600">✓</span></div><div class="mt-4 h-1.5 rounded-full bg-slate-100"><div class="h-1.5 rounded-full bg-green-500" style="width:<?=$pct?>%"></div></div></div><div class="shadow-soft rounded-xl border border-slate-100 bg-white p-5"><p class="text-sm text-slate-500">Pendências financeiras</p><div class="mt-4 flex items-end justify-between"><strong class="text-3xl text-amber-600"><?=e($dev)?></strong><span class="rounded-lg bg-amber-50 px-3 py-2 text-amber-600">!</span></div><p class="mt-3 text-xs text-slate-400">Acompanhar cobranças</p></div><div class="shadow-soft rounded-xl border border-slate-100 bg-white p-5"><p class="text-sm text-slate-500">Arrecadação no mês</p><div class="mt-4 flex items-end justify-between"><strong class="text-2xl">R$ <?=e(number_format($arr,2,',','.'))?></strong><span class="rounded-lg bg-violet-50 px-3 py-2 text-violet-600">R$</span></div><p class="mt-3 text-xs text-slate-400">Pagamentos confirmados</p></div></div><div class="mt-7 grid gap-6 xl:grid-cols-3"><section class="shadow-soft rounded-xl border border-slate-100 bg-white p-6 xl:col-span-2"><div class="mb-6 flex items-center justify-between"><div><h3 class="font-bold">Atividade recente</h3><p class="mt-1 text-xs text-slate-400">Associados adicionados recentemente</p></div><a href="<?=e(app_url('admin/associados.php'))?>" class="text-sm font-semibold text-blue-600">Ver todos →</a></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="border-b border-slate-100 text-xs uppercase tracking-wider text-slate-400"><tr><th class="pb-3">Associado</th><th class="pb-3">Matrícula</th><th class="pb-3">Status</th></tr></thead><tbody><?php foreach($recent as $r):$green=$r['status_financeiro']==='EM_DIA';?><tr class="border-b border-slate-50"><td class="py-4 font-semibold"><?=e($r['nome'])?></td><td class="py-4 text-slate-500"><?=e($r['matricula'])?></td><td class="py-4"><span class="rounded-full px-3 py-1 text-xs font-semibold <?=$green?'bg-green-50 text-green-700':'bg-amber-50 text-amber-700'?>"><?=e($green?'Em dia':'Pendente')?></span></td></tr><?php endforeach;?></tbody></table></div></section><section class="shadow-soft rounded-xl border border-slate-100 bg-white p-6"><h3 class="font-bold">Saúde da base</h3><p class="mt-1 text-xs text-slate-400">Distribuição dos associados</p><div class="mt-9 space-y-7"><div><div class="mb-2 flex justify-between text-sm"><span>Em dia</span><b class="text-green-600"><?=e($dia)?></b></div><div class="h-2 rounded-full bg-green-500" style="width:<?=($total?$dia/$total*100:0)?>%"></div></div><div><div class="mb-2 flex justify-between text-sm"><span>Pendentes</span><b class="text-amber-600"><?=e($dev)?></b></div><div class="h-2 rounded-full bg-amber-500" style="width:<?=($total?$dev/$total*100:0)?>%"></div></div></div></section></div><?php admin_end();